// Helper function to return SVG paths for suits
const getSuitPath = (suit: string) => {
  switch (suit) {
    case "Spades":
      return "M12,2.5C11.5,2.5 6.5,8 6.5,12.5C6.5,15.8 8.8,18 11,18C11,18 11,21.5 8.5,21.5L15.5,21.5C13,21.5 13,18 13,18C15.2,18 17.5,15.8 17.5,12.5C17.5,8 12.5,2.5 12,2.5Z";
    case "Hearts":
      return "M12,21.35L10.55,20.03C5.4,15.36 2,12.28 2,8.5C2,5.42 4.42,3 7.5,3C9.24,3 10.91,3.81 12,5.09C13.09,3.81 14.76,3 16.5,3C19.58,3 22,5.42 22,8.5C22,12.28 18.6,15.36 13.45,20.04L12,21.35Z";
    case "Diamonds":
      return "M12,2L3,12L12,22L21,12Z";
    case "Clubs":
      return "M12,2C10.1,2 8.5,3.6 8.5,5.5C8.5,6.4 8.8,7.2 9.4,7.9C7.4,8.5 6,10.3 6,12.5C6,15.3 8.2,17.5 11,17.5C11,17.5 11,22 8,22L16,22C13,22 13,17.5 13,17.5C15.8,17.5 18,15.3 18,12.5C18,10.3 16.6,8.5 14.6,7.9C15.2,7.2 15.5,6.4 15.5,5.5C15.5,3.6 13.9,2 12,2Z";
    default:
      return "";
  }
};

// High-fidelity Playing Card Component
interface CardProps {
  suit: "Spades" | "Hearts" | "Diamonds" | "Clubs";
  value: string;
  primaryColor: string;
  secondaryColor: string;
  accentColor: string;
  style?: React.CSSProperties;
}

const Card: React.FC<CardProps> = ({
  suit,
  value,
  primaryColor,
  secondaryColor,
  accentColor,
  style,
}) => {
  const isRed = suit === "Hearts" || suit === "Diamonds";
  const iconColor = isRed ? accentColor : primaryColor;

  return (
    <div
      style={{
        width: "100%",
        height: "100%",
        backgroundColor: "#111111",
        borderRadius: "10px",
        border: `2.5px solid ${primaryColor}`,
        boxShadow: "0px 12px 24px rgba(0,0,0,0.7)",
        overflow: "hidden",
        position: "relative",
        boxSizing: "border-box",
        ...style,
      }}
    >
      {/* Background card pattern */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: "linear-gradient(135deg, rgba(255,255,255,0.05) 0%, rgba(0,0,0,0) 80%)",
          pointerEvents: "none",
        }}
      />
      
      {/* Golden Inner border */}
      <div
        style={{
          position: "absolute",
          top: 4,
          left: 4,
          right: 4,
          bottom: 4,
          border: `1px solid ${secondaryColor}`,
          borderRadius: "6px",
          opacity: 0.5,
          boxSizing: "border-box",
        }}
      />

      {/* Top Left Symbol & Value */}
      <div
        style={{
          position: "absolute",
          top: 8,
          left: 8,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          fontFamily: cinzelFamily,
          color: iconColor,
          lineHeight: 1,
        }}
      >
        <span style={{ fontSize: "18px", fontWeight: "bold" }}>{value}</span>
        <svg width="12" height="12" viewBox="0 0 24 24" style={{ marginTop: 2 }}>
          <path d={getSuitPath(suit)} fill={iconColor} />
        </svg>
      </div>

      {/* Center Giant Symbol */}
      <div
        style={{
          position: "absolute",
          top: "50%",
          left: "50%",
          transform: "translate(-50%, -50%)",
          width: "45%",
          height: "45%",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        <svg width="100%" height="100%" viewBox="0 0 24 24">
          <path d={getSuitPath(suit)} fill={iconColor} />
        </svg>
      </div>

      {/* Bottom Right Symbol & Value (rotated) */}
      <div
        style={{
          position: "absolute",
          bottom: 8,
          right: 8,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          fontFamily: cinzelFamily,
          color: iconColor,
          lineHeight: 1,
          transform: "rotate(180deg)",
        }}
      >
        <span style={{ fontSize: "18px", fontWeight: "bold" }}>{value}</span>
        <svg width="12" height="12" viewBox="0 0 24 24" style={{ marginTop: 2 }}>
          <path d={getSuitPath(suit)} fill={iconColor} />
        </svg>
      </div>
    </div>
  );
};

// 3D-styled Poker Chip Stacks Component
const ChipStack: React.FC<{
  count: number;
  height: number;
  primaryColor: string;
}> = ({ count, height, primaryColor }) => {
  const chipHeight = height / count;
  const chipWidth = height * 0.95;

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column-reverse",
        alignItems: "center",
        width: chipWidth,
        height: height + (count * 2),
        position: "relative",
      }}
    >
      {Array.from({ length: count }).map((_, i) => {
        const offsetLeft = i * 1.5; 
        const offsetBottom = i * (chipHeight * 0.72); 

        return (
          <div
            key={i}
            style={{
              position: "absolute",
              bottom: offsetBottom,
              left: offsetLeft,
              width: chipWidth,
              height: chipHeight,
              borderRadius: `${chipHeight * 0.3}px`,
              border: `1.5px solid ${primaryColor}`,
              boxSizing: "border-box",
              background: `repeating-linear-gradient(90deg, #111111 0px, #111111 10px, ${primaryColor} 10px, ${primaryColor} 20px)`,
              boxShadow: "0px 3px 6px rgba(0,0,0,0.6)",
            }}
          />
        );
      })}
    </div>
  );
};

