const PokerIntroLowerThird: React.FC<PokerIntroLowerThirdProps> = ({
  backgroundColor = "#1a0405",
  transparentBackground = true,
  durationInSeconds = 8,
  title = "HIGH STAKES POKER",
  subtitle = "BIG BLINDS. BIG MOVES.",
  primaryColor = "#cca152",
  secondaryColor = "#eecb82",
  panelBgColor = "#121212",
  accentColor = "#b31f24",
  card1Suite = "Spades",
  card2Suite = "Hearts",
  card1Value = "A",
  card2Value = "K",
  showChips = true,
  showCards = true,
  positionX = 0.08,
  positionY = 0.72,
  scale = 1.0,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Handle transparent background configuration safely
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout calculations
  const panelWidth = width * 0.62;
  const panelHeight = height * 0.15;
  const cardWidth = panelHeight * 0.76;
  const cardHeight = panelHeight * 1.12;

  const durationInFrames = durationInSeconds * fps;

  // MASTER TIMING LOGIC
  const outroStartFrame = durationInFrames - 30;
  const outroActive = frame >= outroStartFrame;

  // Outro Progress
  const outroProgress = interpolate(
    frame,
    [outroStartFrame, durationInFrames - 5],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // 1. Panel Intro Spring
  const panelSpring = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 80, mass: 0.9 },
  });

  const panelX = outroActive
    ? interpolate(outroProgress, [0, 1], [0, -width * 0.8])
    : interpolate(panelSpring, [0, 1], [-width * 0.8, 0]);

  // Dynamic vertical off-screen translation distance calculated to place components fully off-screen at start
  const offscreenY = height - (height * positionY) + 300;

  // 2. Playing Cards Spring (Delayed)
  const cardsSpring = spring({
    frame: frame - 15,
    fps,
    config: { damping: 14, stiffness: 70 },
  });

  const cardsY = outroActive
    ? interpolate(outroProgress, [0, 0.8], [0, offscreenY])
    : interpolate(cardsSpring, [0, 1], [offscreenY, 0]);

  const cardsScale = outroActive
    ? interpolate(outroProgress, [0, 0.8], [1, 0.4])
    : interpolate(cardsSpring, [0, 1], [0.4, 1]);

  // 3. Chip Stacks Timing
  const stack1Spring = spring({
    frame: frame - 18,
    fps,
    config: { damping: 12, stiffness: 70 },
  });
  const stack1Y = outroActive
    ? interpolate(outroProgress, [0, 0.7], [0, offscreenY])
    : interpolate(stack1Spring, [0, 1], [offscreenY, 0]);

  const stack2Spring = spring({
    frame: frame - 22,
    fps,
    config: { damping: 12, stiffness: 70 },
  });
  const stack2Y = outroActive
    ? interpolate(outroProgress, [0.1, 0.8], [0, offscreenY])
    : interpolate(stack2Spring, [0, 1], [offscreenY, 0]);

  // 4. Foreground Main Chip Timing
  const mainChipSpring = spring({
    frame: frame - 25,
    fps,
    config: { damping: 13, stiffness: 75 },
  });
  const mainChipY = outroActive
    ? interpolate(outroProgress, [0.15, 0.9], [0, offscreenY])
    : interpolate(mainChipSpring, [0, 1], [offscreenY, 0]);

  const mainChipRotate = outroActive
    ? interpolate(outroProgress, [0.15, 0.9], [0, -360])
    : interpolate(mainChipSpring, [0, 1], [-360, 0]);

  const mainChipScale = outroActive
    ? interpolate(outroProgress, [0.15, 0.9], [1, 0])
    : interpolate(mainChipSpring, [0, 1], [0, 1]);

  // 5. Text Reveal Spring
  const textSpring = spring({
    frame: frame - 24,
    fps,
    config: { damping: 15, stiffness: 85 },
  });

  const textOpacity = outroActive
    ? interpolate(outroProgress, [0, 0.5], [1, 0])
    : interpolate(textSpring, [0, 1], [0, 1]);

  const textTranslateX = outroActive
    ? interpolate(outroProgress, [0, 0.5], [0, -40])
    : interpolate(textSpring, [0, 1], [-40, 0]);

  // 6. Gold Metallic Sweep Reflection Effect
  const sweepCycle = 130; 
  const sweepFrame = (frame - 30) % sweepCycle;
  const sweepProgress = interpolate(
    sweepFrame,
    [0, 40],
    [-50, 250],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const showSweep = frame >= 30 && frame < outroStartFrame && sweepFrame <= 45;
  const sweepX = interpolate(sweepProgress, [-50, 250], [-panelWidth * 0.1, panelWidth * 1.1]);

  // Dynamic subtle pulse of lights during idle
  const idlePulse = Math.sin(frame * 0.07) * 0.08 + 0.92;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none" }}>
      {/* Lower Third Main Container */}
      <div
        style={{
          position: "absolute",
          left: width * positionX,
          top: height * positionY,
          transform: `scale(${scale})`,
          transformOrigin: "left center",
          width: panelWidth,
          height: panelHeight,
          display: "flex",
          alignItems: "center",
          zIndex: 10,
          transition: "none",
        }}
      >
        {/* CARDS (Behind everything else) */}
        {showCards && (
          <>
            <div
              style={{
                position: "absolute",
                left: panelHeight * 0.52,
                top: -cardHeight * 0.42,
                width: cardWidth,
                height: cardHeight,
                transform: `translateY(${cardsY}px) rotate(${-12 + cardsY * 0.04}deg) scale(${cardsScale})`,
                zIndex: -2,
                transformOrigin: "bottom center",
                transition: "none",
              }}
            >
              <Card
                suit={card1Suite}
                value={card1Value}
                primaryColor={primaryColor}
                secondaryColor={secondaryColor}
                accentColor={accentColor}
              />
            </div>
            <div
              style={{
                position: "absolute",
                left: panelHeight * 1.1,
                top: -cardHeight * 0.38,
                width: cardWidth,
                height: cardHeight,
                transform: `translateY(${cardsY}px) rotate(${8 - cardsY * 0.04}deg) scale(${cardsScale})`,
                zIndex: -1,
                transformOrigin: "bottom center",
                transition: "none",
              }}
            >
              <Card
                suit={card2Suite}
                value={card2Value}
                primaryColor={primaryColor}
                secondaryColor={secondaryColor}
                accentColor={accentColor}
              />
            </div>
          </>
        )}

        {/* CHIP STACKS (Behind main panel on left) */}
        {showChips && (
          <>
            {/* Left Stack */}
            <div
              style={{
                position: "absolute",
                left: -panelHeight * 0.38,
                bottom: panelHeight * 0.04,
                transform: `translateY(${stack1Y}px)`,
                zIndex: -1,
                transition: "none",
              }}
            >
              <ChipStack count={8} height={panelHeight * 0.78} primaryColor={primaryColor} />
            </div>
            {/* Right Stack */}
            <div
              style={{
                position: "absolute",
                left: -panelHeight * 0.04,
                bottom: panelHeight * 0.12,
                transform: `translateY(${stack2Y}px)`,
                zIndex: -1,
                transition: "none",
              }}
            >
              <ChipStack count={6} height={panelHeight * 0.62} primaryColor={primaryColor} />
            </div>
          </>
        )}

        {/* MAIN PANEL */}
        <div
          style={{
            position: "absolute",
            left: 0,
            top: 0,
            width: panelWidth,
            height: panelHeight,
            transform: `translateX(${panelX}px)`,
            zIndex: 1,
            transition: "none",
          }}
        >
          {/* SVG Background Panel with Premium Bevels & Outline */}
          <svg
            width={panelWidth}
            height={panelHeight}
            viewBox={`0 0 ${panelWidth} ${panelHeight}`}
            style={{ position: "absolute", top: 0, left: 0 }}
          >
            <defs>
              <linearGradient id="panelGold" x1="0%" y1="0%" x2="100%" y2="100%">
                <stop offset="0%" stopColor="#7a5f1a" />
                <stop offset="25%" stopColor={secondaryColor} />
                <stop offset="50%" stopColor="#ffffff" />
                <stop offset="75%" stopColor={secondaryColor} />
                <stop offset="100%" stopColor="#8d6e24" />
              </linearGradient>

              <linearGradient id="panelDark" x1="0%" y1="0%" x2="100%" y2="0%">
                <stop offset="0%" stopColor={panelBgColor} />
                <stop offset="40%" stopColor="#1e1e1e" />
                <stop offset="100%" stopColor="#0a0a0a" />
              </linearGradient>

              <linearGradient id="bottomLightBeam" x1="0%" y1="0%" x2="100%" y2="0%">
                <stop offset="0%" stopColor="transparent" />
                <stop offset="15%" stopColor={primaryColor} />
                <stop offset="50%" stopColor="#ffffff" />
                <stop offset="85%" stopColor={primaryColor} />
                <stop offset="100%" stopColor="transparent" />
              </linearGradient>
            </defs>

            {/* Panel Shadow */}
            <path
              d={`M ${panelHeight * 0.82} ${panelHeight * 0.1}
                  L ${panelWidth * 0.9} ${panelHeight * 0.1}
                  L ${panelWidth * 0.94} ${panelHeight * 0.86}
                  L ${panelHeight * 0.92} ${panelHeight * 0.86} Z`}
              fill="rgba(0,0,0,0.65)"
              transform="translate(6, 6)"
            />

            {/* Back Gold Border Panel Accent */}
            <path
              d={`M ${panelHeight * 0.82} ${panelHeight * 0.08}
                  L ${panelWidth * 0.91} ${panelHeight * 0.08}
                  L ${panelWidth * 0.952} ${panelHeight * 0.88}
                  L ${panelHeight * 0.9} ${panelHeight * 0.88} Z`}
              fill="url(#panelGold)"
            />

            {/* Inner Metallic Dark Face */}
            <path
              d={`M ${panelHeight * 0.84} ${panelHeight * 0.1}
                  L ${panelWidth * 0.904} ${panelHeight * 0.1}
                  L ${panelWidth * 0.944} ${panelHeight * 0.86}
                  L ${panelHeight * 0.92} ${panelHeight * 0.86} Z`}
              fill="url(#panelDark)"
            />

            {/* Bright Bottom Gold Highlight Rail */}
            <line
              x1={panelHeight * 0.94}
              y1={panelHeight * 0.94}
              x2={panelWidth * 0.89}
              y2={panelHeight * 0.94}
              stroke="url(#panelGold)"
              strokeWidth={3}
              opacity={idlePulse}
              style={{ filter: "drop-shadow(0px 0px 5px rgba(238,203,130,0.7))" }}
            />
          </svg>

          {/* INNER TEXT & SUBTITLE LAYER */}
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              justifyContent: "center",
              alignItems: "flex-start",
              marginLeft: panelHeight * 1.35,
              height: "100%",
              zIndex: 3,
              transform: `translateX(${textTranslateX}px)`,
              opacity: textOpacity,
              transition: "none",
            }}
          >
            {/* Title - Bold Uppercase Gold Condensed */}
            <div
              style={{
                fontFamily: bebasFamily,
                fontSize: panelHeight * 0.38,
                fontWeight: "bold",
                background: `linear-gradient(to bottom, ${secondaryColor} 0%, ${primaryColor} 65%, #8d6e24 100%)`,
                WebkitBackgroundClip: "text",
                WebkitTextFillColor: "transparent",
                letterSpacing: "1px",
                lineHeight: 0.95,
                textTransform: "uppercase",
                filter: "drop-shadow(0px 2px 4px rgba(0,0,0,0.5))",
                transition: "none",
              }}
            >
              {title}
            </div>

            {/* Subtitle Divider line + centered subtitle text */}
            <div
              style={{
                display: "flex",
                alignItems: "center",
                width: panelWidth * 0.65,
                marginTop: panelHeight * 0.04,
                transition: "none",
              }}
            >
              <div style={{ flex: 1, height: "1px", background: `linear-gradient(to right, transparent, ${primaryColor}, transparent)`, opacity: 0.6 }} />
              <div
                style={{
                  fontFamily: montserratFamily,
                  fontSize: panelHeight * 0.105,
                  fontWeight: "600",
                  color: "#ffffff",
                  opacity: 0.9,
                  letterSpacing: "4px",
                  padding: "0 10px",
                  whiteSpace: "nowrap",
                  textTransform: "uppercase",
                  textShadow: "0px 1px 3px rgba(0,0,0,0.8)",
                  transition: "none",
                }}
              >
                {subtitle}
              </div>
              <div style={{ flex: 1, height: "1px", background: `linear-gradient(to right, transparent, ${primaryColor}, transparent)`, opacity: 0.6 }} />
            </div>
          </div>

          {/* RIGHT SIDE SPADE ACCENT DECORATION */}
          <div
            style={{
              position: "absolute",
              right: panelWidth * 0.13,
              top: "47%",
              transform: "translateY(-50%)",
              width: panelHeight * 0.22,
              height: panelHeight * 0.22,
              opacity: textOpacity,
              transition: "none",
            }}
          >
            <svg viewBox="0 0 24 24" style={{ width: "100%", height: "100%", filter: "drop-shadow(0px 2px 4px rgba(0,0,0,0.5))" }}>
              <path d={getSuitPath("Spades")} fill="url(#panelGold)" />
            </svg>
          </div>

          {/* LIGHT SWEEP SHIMMER EFFECT OVERLAY */}
          {showSweep && (
            <div
              style={{
                position: "absolute",
                top: panelHeight * 0.08,
                height: panelHeight * 0.8,
                width: panelHeight * 0.4,
                background: `linear-gradient(90deg, transparent 0%, rgba(255, 255, 255, 0.28) 50%, transparent 100%)`,
                transform: `skewX(-28deg) translateX(${sweepX}px)`,
                mixBlendMode: "overlay",
                pointerEvents: "none",
                zIndex: 4,
                transition: "none",
              }}
            />
          )}
        </div>

        {/* FOREGROUND MAIN ROTATING CHIP */}
        {showChips && (
          <div
            style={{
              position: "absolute",
              left: panelHeight * 0.1,
              top: -panelHeight * 0.04,
              transform: `translateY(${mainChipY}px) rotate(${mainChipRotate}deg) scale(${mainChipScale})`,
              zIndex: 5,
              transition: "none",
            }}
          >
            <MainChip
              size={panelHeight * 1.1}
              primaryColor={primaryColor}
              secondaryColor={secondaryColor}
              accentColor={accentColor}
            />
          </div>
        )}
      </div>
    </AbsoluteFill>
  );
};

